export const B6_RVR: Record<string, string> = {
  "sor-psa34-17": "Clamaron los justos, y Jehov\u{e1} oy\u{f3}, y libr\u{f3}los de todas sus angustias.",
  "sor-psa40-2": "E h\u{ed}zome sacar de un lago de miseria, del lodo cenagoso; y puso mis pies sobre pe\u{f1}a, y enderez\u{f3} mis pasos.",
  "sor-psa13-1": "\u{bf}HASTA cu\u{e1}ndo, Jehov\u{e1}? \u{bf}me olvidar\u{e1}s para siempre? \u{bf}hasta cu\u{e1}ndo esconder\u{e1}s tu rostro de m\u{ed}?",
  "sor-1ki19-7": "Y volviendo el \u{e1}ngel de Jehov\u{e1} la segunda vez, toc\u{f3}le, diciendo: Lev\u{e1}ntate, come: porque gran camino te resta.",
  "sor-isa61-3": "A ordenar \u{e1} Si\u{f3}n \u{e1} los enlutados, para darles gloria en lugar de ceniza, \u{f3}leo de gozo en lugar del luto, manto de alegr\u{ed}a en lugar del esp\u{ed}ritu angustiado; y ser\u{e1}n llamados \u{e1}rboles de justicia, plant\u{ed}o de Jehov\u{e1}, para gloria suya.",
  "sor-psa3-3": "Mas t\u{fa}, Jehov\u{e1}, eres escudo alrededor de m\u{ed}: mi gloria, y el que ensalza mi cabeza.",
  "sor-2co1-3": "Bendito sea el Dios y Padre del Se\u{f1}or Jesucristo, el Padre de misericordias, y el Dios de toda consolaci\u{f3}n,",
  "sor-2co4-8": "Estando atribulados en todo, mas no angustiados; en apuros, mas no desesperamos;",
  "sor-psa61-2": "Desde el cabo de la tierra clamar\u{e9} \u{e1} ti, cuando mi coraz\u{f3}n desmayare: \u{e1} la pe\u{f1}a m\u{e1}s alta que yo me conduzcas.",
  "sor-psa94-19": "En la multitud de mis pensamientos dentro de m\u{ed}, tus consolaciones alegraban mi alma.",
  "sor-isa42-3": "No quebrar\u{e1} la ca\u{f1}a cascada, ni apagar\u{e1} el p\u{e1}bilo que humeare: sacar\u{e1} el juicio \u{e1} verdad.",
  "sor-psa56-8": "Mis hu\u{ed}das has t\u{fa} contado: pon mis l\u{e1}grimas en tu redoma: \u{bf}no est\u{e1}n ellas en tu libro?",
  "sor-jhn11-35": "Y llor\u{f3} Jes\u{fa}s.",
  "sor-psa126-5": "Los que sembraron con l\u{e1}grimas, con regocijo segar\u{e1}n.",
  "crs-1co15-3": "Porque primeramente os he ense\u{f1}ado lo que asimismo recib\u{ed}: Que Cristo fu\u{e9} muerto por nuestros pecados, conforme \u{e1} las Escrituras;",
  "crs-1co15-4": "Y que fu\u{e9} sepultado, y que resucit\u{f3} al tercer d\u{ed}a, conforme \u{e1} las Escrituras;",
  "crs-1co15-20": "Mas ahora Cristo ha resucitado de los muertos; primicias de los que durmieron es hecho.",
  "crs-rom6-4": "Porque somos sepultados juntamente con \u{e9}l \u{e1} muerte por el bautismo; para que como Cristo resucit\u{f3} de los muertos por la gloria del Padre, as\u{ed} tambi\u{e9}n nosotros andemos en novedad de vida.",
  "crs-1pe2-24": "El cual mismo llev\u{f3} nuestros pecados en su cuerpo sobre el madero, para que nosotros siendo muertos \u{e1} los pecados, vivamos \u{e1} la justicia: por la herida del cual hab\u{e9}is sido sanados.",
  "crs-1pe3-18": "Porque tambi\u{e9}n Cristo padeci\u{f3} una vez por los pecados, el justo por los injustos, para llevarnos \u{e1} Dios, siendo \u{e1} la verdad muerto en la carne, pero vivificado en esp\u{ed}ritu;",
  "crs-gal6-14": "Mas lejos est\u{e9} de m\u{ed} gloriarme, sino en la cruz de nuestro Se\u{f1}or Jesucristo, por el cual el mundo me es crucificado \u{e1} m\u{ed}, y yo al mundo.",
  "crs-col2-14": "Rayendo la c\u{e9}dula de los ritos que nos era contraria, que era contra nosotros, quit\u{e1}ndola de en medio y enclav\u{e1}ndola en la cruz;",
  "crs-mat28-6": "No est\u{e1} aqu\u{ed}; porque ha resucitado, como dijo. Venid, ved el lugar donde fu\u{e9} puesto el Se\u{f1}or.",
  "crs-jhn19-30": "Y como Jes\u{fa}s tom\u{f3} el vinagre, dijo: Consumado es. Y habiendo inclinado la cabeza, di\u{f3} el esp\u{ed}ritu.",
  "crs-rom4-25": "El cual fu\u{e9} entregado por nuestros delitos, y resucitado para nuestra justificaci\u{f3}n.",
  "crs-1co1-18": "Porque la palabra de la cruz es locura \u{e1} los que se pierden; mas \u{e1} los que se salvan, es \u{e1} saber, \u{e1} nosotros, es potencia de Dios.",
  "crs-isa53-6": "Todos nosotros nos descarriamos como ovejas, cada cual se apart\u{f3} por su camino: mas Jehov\u{e1} carg\u{f3} en \u{e9}l el pecado de todos nosotros.",
  "crs-2co5-21": "Al que no conoci\u{f3} pecado, hizo pecado por nosotros, para que nosotros fu\u{e9}semos hechos justicia de Dios en \u{e9}l.",
  "prm-2co1-20": "Porque todas las promesas de Dios son en \u{e9}l S\u{ed}, y en \u{e9}l Am\u{e9}n, por nosotros \u{e1} gloria de Dios.",
  "prm-num23-19": "Dios no es hombre, para que mienta; ni hijo de hombre para que se arrepienta: el dijo, \u{bf}y no har\u{e1}?; habl\u{f3}, \u{bf}y no lo ejecutar\u{e1}?",
  "prm-isa40-8": "S\u{e9}case la hierba, c\u{e1}ese la flor: mas la palabra del Dios nuestro permanece para siempre.",
  "prm-jos21-45": "No falt\u{f3} palabra de todas la buenas que habl\u{f3} Jehov\u{e1} \u{e1} la casa de Israel; todo se cumpli\u{f3}.",
  "prm-2pe1-4": "Por las cuales nos son dadas preciosas y grand\u{ed}simas promesas, para que por ellas fueseis hechos participantes de la naturaleza divina, habiendo hu\u{ed}do de la corrupci\u{f3}n que est\u{e1} en el mundo por concupiscencia.",
  "prm-2pe3-9": "El Se\u{f1}or no tarda su promesa, como algunos la tienen por tardanza; sino que es paciente para con nosotros, no queriendo que ninguno perezca, sino que todos procedan al arrepentimiento.",
  "prm-isa55-11": "As\u{ed} ser\u{e1} mi palabra que sale de mi boca: no volver\u{e1} \u{e1} m\u{ed} vac\u{ed}a, antes har\u{e1} lo que yo quiero, y ser\u{e1} prosperada en aquello para que la envi\u{e9}.",
  "prm-heb6-18": "Para que por dos cosas inmutables, en las cuales es imposible que Dios mienta, tengamos un fort\u{ed}simo consuelo, los que nos acogemos \u{e1} trabarnos de la esperanza propuesta:",
  "prm-jhn10-28": "Y yo les doy vida eterna: y no perecer\u{e1}n para siempre, ni nadie las arrebatar\u{e1} de mi mano.",
  "prm-psa91-11": "Pues que \u{e1} sus \u{e1}ngeles mandar\u{e1} acerca de ti, que te guarden en todos tus caminos.",
  "prm-isa54-10": "Porque los montes se mover\u{e1}n, y los collados temblar\u{e1}n; mas no se apartar\u{e1} de ti mi misericordia, ni el pacto de mi paz vacilar\u{e1}, dijo Jehov\u{e1}, el que tiene misericordia de ti.",
  "prm-mat24-35": "El cielo y la tierra pasar\u{e1}n, mas mis palabras no pasar\u{e1}n.",
  "prm-deu7-9": "Conoce, pues, que Jehov\u{e1} tu Dios es Dios, Dios fiel, que guarda el pacto y la misericordia \u{e1} los que le aman y guardan sus mandamientos, hasta las mil generaciones;",
  "prm-1ki8-56": "Bendito sea Jehov\u{e1}, que ha dado reposo \u{e1} su pueblo Israel, conforme \u{e1} todo lo que \u{e9}l hab\u{ed}a dicho; ninguna palabra de todas sus promesas que expres\u{f3} por Mois\u{e9}s su siervo, ha faltado.",
  "obe-jhn14-15": "Si me am\u{e1}is, guardad mis mandamientos;",
  "obe-jhn14-21": "El que tiene mis mandamientos, y los guarda, aqu\u{e9}l es el que me ama; y el que me ama, ser\u{e1} amado de mi Padre, y yo le amar\u{e9}, y me manifestar\u{e9} \u{e1} \u{e9}l.",
  "obe-1sa15-22": "Y Samuel dijo: \u{bf}Tiene Jehov\u{e1} tanto contentamiento con los holocaustos y v\u{ed}ctimas, como en obedecer \u{e1} las palabras de Jehov\u{e1}? Ciertamente el obedecer es mejor que los sacrificios; y el prestar atenci\u{f3}n que el sebo de los carneros:",
  "obe-jas1-22": "Mas sed hacedores de la palabra, y no tan solamente oidores, enga\u{f1}\u{e1}ndoos \u{e1} vosotros mismos.",
  "obe-luk6-46": "\u{bf}Por qu\u{e9} me llam\u{e1}is, Se\u{f1}or, Se\u{f1}or, y no hac\u{e9}is lo que digo?",
  "obe-luk11-28": "Y \u{e9}l dijo: Antes bienaventurados los que oyen la palabra de Dios, y la guardan.",
  "obe-1jn5-3": "Porque este es el amor de Dios, que guardemos sus mandamientos; y sus mandamientos no son penosos.",
  "obe-mat7-24": "Cualquiera, pues, que me oye estas palabras, y las hace, le comparar\u{e9} \u{e1} un hombre prudente, que edific\u{f3} su casa sobre la pe\u{f1}a;",
  "obe-act5-29": "Y respondiendo Pedro y los ap\u{f3}stoles, dijeron: Es menester obedecer \u{e1} Dios antes que \u{e1} los hombres.",
  "obe-psa119-60": "Apresur\u{e9}me, y no me retard\u{e9} en guardar tus mandamientos.",
  "obe-jos1-8": "El libro de aquesta ley nunca se apartar\u{e1} de tu boca: antes de d\u{ed}a y de noche meditar\u{e1}s en \u{e9}l, para que guardes y hagas conforme \u{e1} todo lo que en \u{e9}l est\u{e1} escrito: porque entonces har\u{e1}s prosperar tu camino, y todo te saldr\u{e1} bien.",
  "obe-heb5-8": "Y aunque era Hijo, por lo que padeci\u{f3} aprendi\u{f3} la obediencia;",
  "obe-isa1-19": "Si quisiereis y oyereis, comer\u{e9}is el bien de la tierra:",
  "obe-2jn1-6": "Y este es amor, que andemos seg\u{fa}n sus mandamientos. Este es el mandamiento: Que and\u{e9}is en \u{e9}l, como vosotros hab\u{e9}is o\u{ed}do desde el principio.",
  "uni-psa133-1": "\u{a1}MIRAD cu\u{e1}n bueno y cu\u{e1}n delicioso es habitar los hermanos igualmente en uno!",
  "uni-jhn17-21": "Para que todos sean una cosa; como t\u{fa}, oh Padre, en m\u{ed}, y yo en ti, que tambi\u{e9}n ellos sean en nosotros una cosa: para que el mundo crea que t\u{fa} me enviaste.",
  "uni-eph4-3": "Sol\u{ed}citos \u{e1} guardar la unidad del Esp\u{ed}ritu en el v\u{ed}nculo de la paz.",
  "uni-eph4-5": "Un Se\u{f1}or, una fe, un bautismo,",
  "uni-1co1-10": "Os ruego pues, hermanos, por el nombre de nuestro Se\u{f1}or Jesucristo, que habl\u{e9}is todos una misma cosa, y que no haya entre vosotros disensiones, antes se\u{e1}is perfectamente unidos en una misma mente y en un mismo parecer.",
  "uni-1co12-12": "Porque de la manera que el cuerpo es uno, y tiene muchos miembros, empero todos los miembros del cuerpo, siendo muchos, son un cuerpo, as\u{ed} tambi\u{e9}n Cristo.",
  "uni-1co12-26": "Por manera que si un miembro padece, todos los miembros \u{e1} una se duelen; y si un miembro es honrado, todos los miembros \u{e1} una se gozan.",
  "uni-rom12-5": "As\u{ed} muchos somos un cuerpo en Cristo, mas todos miembros los unos de los otros.",
  "uni-rom15-5": "Mas el Dios de la paciencia y de la consolaci\u{f3}n os d\u{e9} que entre vosotros se\u{e1}is un\u{e1}nimes seg\u{fa}n Cristo Jes\u{fa}s;",
  "uni-col3-14": "Y sobre todas estas cosas vest\u{ed}os de caridad, la cual es el v\u{ed}nculo de la perfecci\u{f3}n.",
  "uni-php2-2": "Cumplid mi gozo; que sint\u{e1}is lo mismo, teniendo el mismo amor, un\u{e1}nimes, sintiendo una misma cosa.",
  "uni-act2-42": "Y perseveraban en la doctrina de los ap\u{f3}stoles, y en la comuni\u{f3}n, y en el partimiento del pan, y en las oraciones.",
  "uni-gal3-28": "No hay Jud\u{ed}o, ni Griego; no hay siervo, ni libre; no hay var\u{f3}n, ni hembra: porque todos vosotros sois uno en Cristo Jes\u{fa}s.",
  "uni-heb10-25": "No dejando nuestra congregaci\u{f3}n, como algunos tienen por costumbre, mas exhort\u{e1}ndonos; y tanto m\u{e1}s, cuanto veis que aquel d\u{ed}a se acerca.",
};
